/** Alle scenario-ID's die tot de canonieke rooktest (§2.6) behoren. */
export const UAT_ROOKTEST_IDS: string[] = UAT_SCENARIOS.filter((s) => s.rooktest).map((s) => s.id)

/** Totaal aantal (sub)scenario's per platform, voor de dekkingsteller. */
export function totalSubscenarioCount(): number {
  return UAT_SCENARIOS.reduce((n, s) => n + s.subscenarios.length * s.platforms.length, 0)
}
